def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_threats = 0
    desperate_threats = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > budget * 0.9:
                rich_threats += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_threats += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    if not alive:
        return float(min(budget, 18.0))

    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if tightness < 0:
        tightness = 0.0
    if tightness > 1:
        tightness = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2

    if no_water >= 2:
        urgency += 0.7
    elif no_water >= 1:
        urgency += 0.35

    urgency += 0.35 * tightness
    urgency += 0.08 * min(desperate_threats, 3)

    days_left = max(0, 10 - int(day) + 1)
    reserve_target = max(0.0, days_left * DAILY_SALARY * 0.42)
    spendable = max(0.0, budget - reserve_target)

    base = DAILY_SALARY * (0.34 + 0.42 * urgency)

    if prev_bids:
        high_prev = max(prev_bids)
        low_prev = min(prev_bids)
        if high_prev >= 160:
            react = 32.0 if urgency >= 0.8 else 22.0
        elif high_prev >= 110:
            react = 72.0 if urgency >= 0.75 else 48.0
        elif high_prev >= 70:
            react = min(high_prev + 3.0, 88.0)
        else:
            react = max(38.0, low_prev + 4.0)
        bid = max(base, react)
    else:
        bid = base

    if rich_threats >= 2 and urgency < 0.75:
        bid *= 0.88

    if hp <= 2 or no_water >= 2:
        bid = max(bid, DAILY_SALARY * 0.95)
    elif hp <= 4 or no_water >= 1:
        bid = max(bid, DAILY_SALARY * 0.72)

    if supply >= 23 and urgency < 0.5:
        bid *= 0.82
    elif supply <= 17:
        bid *= 1.12

    cap = budget
    if spendable > 0:
        soft_cap = reserve_target * 0.15 + spendable * (0.55 + 0.35 * min(1.0, urgency))
        cap = min(cap, max(28.0, soft_cap))

    if hp <= 2 or no_water >= 2:
        cap = budget

    bid = min(bid, cap)
    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        max_bid = max(yesterday_bids)

        if my_status['hp'] <= 4:
            bid = min(my_status['budget'], max_bid * 1.05 + 5.0)
        else:
            bid = min(my_status['budget'], max(avg_bid, 60.0))
    else:
        bid = 70.0

    return float(min(my_status['budget'], bid))
